export const DEFAULT_NEXT_ID = n + 1;

export function getInitialState(): StoreState {
  const base: StoreState = {
    items: SEED.map((item) => ({ ...item })),
    dm: "has.a.null",
    shop: "Jastip.Mekkah",
    tagline: "katalog jastip",
    arabicTitle: "مكة",
    ann: "Jika berminat membeli, silakan DM admin.",
    annSub: "Sebutkan nama produk yang kamu mau atau salin keranjang, admin akan balas secepatnya.",
    footerNote: "Katalog Jastip Makkah",
    logo: LOGO,
    adminPass: PASS,
    nextId: DEFAULT_NEXT_ID,
  };
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      const resolvedPass =
        !parsed.adminPass || parsed.adminPass === "admin123" ? PASS : parsed.adminPass;
      return { ...base, ...parsed, adminPass: resolvedPass };
    }
  } catch {
    // ignore storage errors
  }
  return base;
}

export function saveState(state: StoreState): boolean {
  try {
    localStorage.setItem(KEY, JSON.stringify(state));
    return true;
  } catch {
    return false;
  }
}

export function getInitialCart(): CartMap {
  try {
    const raw = localStorage.getItem(CART_KEY);
    if (raw) return JSON.parse(raw) || {};
  } catch {
    // ignore
  }
  return {};
}

export function saveCartState(cart: CartMap): void {
  try {
    localStorage.setItem(CART_KEY, JSON.stringify(cart));
  } catch {
    // ignore
  }
}

export function rp(v: number | null | undefined): string {
  return "Rp" + Number(v || 0).toLocaleString("id-ID");
}

export function isGone(p: Product): boolean {
  return p.stock !== null && p.stock !== undefined && p.stock <= 0;
}

export function dmUrl(dm: string): string {
  const u = (dm || "").trim();
  if (!u) return "";
  if (/^https?:/i.test(u)) return u;
  const h = u.replace(/^@/, "").replace(/\s/g, "");
  const isMob =
    typeof navigator !== "undefined" && /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
  return isMob ? "https://ig.me/m/" + h : "https://instagram.com/" + h;
}

export async function copyText(t: string): Promise<boolean> {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(t);
      return true;
    }
  } catch {
    // fallback below
  }
  try {
    const a = document.createElement("textarea");
    a.value = t;
    a.style.cssText = "position:fixed;opacity:0;pointer-events:none";
    document.body.appendChild(a);
    a.select();
    document.execCommand("copy");
    a.remove();
    return true;
  } catch {
    return false;
  }
}

export function shrinkImage(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onerror = () => reject(new Error("Gagal membaca gambar"));
    r.onload = () => {
      const im = new Image();
      im.onerror = () => reject(new Error("Gambar tidak valid"));
      im.onload = () => {
        const k = Math.min(1, 480 / Math.max(im.width, im.height));
        const c = document.createElement("canvas");
        c.width = im.width * k;
        c.height = im.height * k;
        const ctx = c.getContext("2d");
        if (ctx) {
          ctx.drawImage(im, 0, 0, c.width, c.height);
        }
        resolve(c.toDataURL("image/jpeg", 0.78));
      };
      im.src = String(r.result);
    };
    r.readAsDataURL(file);
  });
}
